-- RMAN 命令（在 RMAN 提示符或 rman target / @脚本 里执行）：
RUN {
  ALLOCATE CHANNEL c1 DEVICE TYPE DISK FORMAT '<backup_dir>/%d_%T_%U.bak';
  BACKUP DATABASE PLUS ARCHIVELOG;
  DELETE NOPROMPT OBSOLETE;
  RELEASE CHANNEL c1;
}

